/**
 * block_enhancedcourseoverview/filter
 *
 * Hand-built AMD equivalent of amd/src/filter.js.
 *
 * This repository does not include Moodle's own build tooling (Grunt +
 * the moodle-local babel/rollup config live in Moodle core), so this file
 * cannot be generated with `grunt amd` here. It is a faithful, manually
 * written AMD translation of the ES module in amd/src/filter.js, kept in
 * sync by hand. Once this plugin is dropped into a full Moodle checkout,
 * regenerate the canonical minified/versioned build with:
 *
 *   grunt amd --root=blocks/enhancedcourseoverview
 *
 * and commit the result over this file.
 */
define(['core/str'], function (Str) {
    'use strict';

    var SELECTORS = {
        FILTER_BUTTON: '.filter-term-btn',
        GROUP_TOGGLE: '.filter-group-toggle',
        GROUP: '.btn-group',
        LOAD_MORE_BUTTON: '[data-action="more-courses"]',
        COURSE_CONTENT: '[data-region="course-content"]',
        COURSE_ITEM: '.course-card, .list-group-item.course-listitem',
        COURSE_NAME: '.coursename',
        COLUMN: '.col.d-flex, .col'
    };

    var LOAD_MORE_TIMEOUT_MS = 5000;

    var waitForUpdate = function (target, timeout) {
        return new Promise(function (resolve) {
            var settled = false;
            var finish = function () {
                if (settled) {
                    return;
                }
                settled = true;
                observer.disconnect();
                resolve();
            };
            var observer = new MutationObserver(finish);
            observer.observe(target, {childList: true, subtree: true});
            setTimeout(finish, timeout);
        });
    };

    /**
     * @param {Element} root
     * @param {Element} filterContainer
     * @param {Object} strings
     */
    function CourseFilter(root, filterContainer, strings) {
        this.root = root;
        this.filterContainer = filterContainer;
        this.strings = strings;
        this.courseContent = root.querySelector(SELECTORS.COURSE_CONTENT);
        this.allLoaded = false;
        this.originalLayout = null;

        this.countIndicator = document.createElement('div');
        this.countIndicator.className = 'course-count-indicator';
        filterContainer.insertAdjacentElement('afterend', this.countIndicator);

        if (this.courseContent) {
            var self = this;
            this.visibilityObserver = new MutationObserver(function () {
                self.updateGroupVisibility();
            });
            this.visibilityObserver.observe(this.courseContent, {childList: true, subtree: true});
        }
    }

    CourseFilter.prototype.saveLayout = function () {
        if (this.originalLayout === null && this.courseContent) {
            this.originalLayout = this.courseContent.innerHTML;
        }
    };

    CourseFilter.prototype.restoreLayout = function () {
        if (this.courseContent && this.originalLayout !== null) {
            this.courseContent.innerHTML = this.originalLayout;
        }
    };

    CourseFilter.prototype.loadAllCourses = function () {
        var self = this;
        if (self.allLoaded || !self.courseContent) {
            return Promise.resolve();
        }

        var clickNext = function () {
            var loadMoreButton = self.root.querySelector(SELECTORS.LOAD_MORE_BUTTON);
            if (!loadMoreButton) {
                self.allLoaded = true;
                return Promise.resolve();
            }
            loadMoreButton.click();
            return waitForUpdate(self.courseContent, LOAD_MORE_TIMEOUT_MS).then(clickNext);
        };

        return clickNext();
    };

    CourseFilter.prototype.getCourseNames = function () {
        var names = Array.prototype.map.call(
            this.root.querySelectorAll(SELECTORS.COURSE_NAME),
            function (el) {
                return el.textContent || '';
            }
        );
        if (names.length) {
            return names;
        }

        return Array.prototype.map.call(
            this.root.querySelectorAll(SELECTORS.COURSE_ITEM),
            function (el) {
                return el.textContent || '';
            }
        );
    };

    CourseFilter.prototype.updateGroupVisibility = function () {
        var courseNames = this.getCourseNames();

        this.filterContainer.querySelectorAll(SELECTORS.GROUP).forEach(function (group) {
            var patterns = Array.prototype.map.call(
                group.querySelectorAll(SELECTORS.FILTER_BUTTON),
                function (button) {
                    return button.getAttribute('data-pattern');
                }
            );
            var hasMatch = patterns.some(function (pattern) {
                return courseNames.some(function (name) {
                    return name.indexOf(pattern) !== -1;
                });
            });
            group.classList.toggle('enhancedcourseoverview-group-hidden', !hasMatch);
        });
    };

    CourseFilter.prototype.applyFilters = function (patterns) {
        var self = this;
        var cards = self.root.querySelectorAll(SELECTORS.COURSE_ITEM);
        var visible = 0;

        cards.forEach(function (card) {
            var column = card.closest(SELECTORS.COLUMN) || card;

            if (patterns.length === 0) {
                column.style.removeProperty('display');
                visible++;
                return;
            }

            var nameEl = card.querySelector(SELECTORS.COURSE_NAME);
            var haystack = (nameEl ? nameEl.textContent : card.textContent) || '';
            var matches = patterns.some(function (pattern) {
                return haystack.indexOf(pattern) !== -1;
            });

            if (matches) {
                column.style.removeProperty('display');
                visible++;
            } else {
                column.style.setProperty('display', 'none', 'important');
            }
        });

        self.toggleEmptyMessage(patterns.length > 0 && visible === 0);
        self.countIndicator.textContent = patterns.length === 0 ?
            '' : self.strings.showing.replace('{visible}', visible).replace('{total}', cards.length);
    };

    CourseFilter.prototype.toggleEmptyMessage = function (show) {
        var message = this.root.querySelector('.enhancedcourseoverview-empty');

        if (!show) {
            if (message) {
                message.remove();
            }
            return;
        }

        if (!message && this.courseContent) {
            message = document.createElement('div');
            message.className = 'alert alert-info enhancedcourseoverview-empty';
            message.textContent = this.strings.nomatches;
            this.courseContent.appendChild(message);
        }
    };

    CourseFilter.prototype.syncButtonStates = function () {
        this.filterContainer.querySelectorAll(SELECTORS.FILTER_BUTTON).forEach(function (button) {
            button.setAttribute('aria-pressed', button.classList.contains('active') ? 'true' : 'false');
        });

        this.filterContainer.querySelectorAll(SELECTORS.GROUP).forEach(function (group) {
            var buttons = group.querySelectorAll(SELECTORS.FILTER_BUTTON);
            var toggle = group.querySelector(SELECTORS.GROUP_TOGGLE);
            if (!toggle || buttons.length === 0) {
                return;
            }
            var activeCount = group.querySelectorAll(SELECTORS.FILTER_BUTTON + '.active').length;
            toggle.classList.toggle('active', activeCount === buttons.length);
            toggle.classList.toggle('filter-group-toggle-partial', activeCount > 0 && activeCount < buttons.length);
            toggle.setAttribute('aria-pressed', activeCount === buttons.length ? 'true' : 'false');
        });
    };

    CourseFilter.prototype.refresh = function () {
        var self = this;
        self.syncButtonStates();

        var active = self.filterContainer.querySelectorAll(SELECTORS.FILTER_BUTTON + '.active');
        var patterns = Array.prototype.map.call(active, function (button) {
            return button.getAttribute('data-pattern');
        });

        if (patterns.length === 0) {
            self.restoreLayout();
            self.countIndicator.textContent = '';
            self.toggleEmptyMessage(false);
            return Promise.resolve();
        }

        self.saveLayout();

        var hasMoreToLoad = !self.allLoaded && self.root.querySelector(SELECTORS.LOAD_MORE_BUTTON);
        var loadPromise = Promise.resolve();
        if (hasMoreToLoad) {
            self.countIndicator.textContent = self.strings.loading;
            loadPromise = self.loadAllCourses();
        }

        return loadPromise.then(function () {
            self.applyFilters(patterns);
        });
    };

    /**
     * @param {String} uniqid
     * @return {Promise}
     */
    var init = function (uniqid) {
        var filterContainer = document.getElementById(uniqid);
        if (!filterContainer) {
            return Promise.resolve();
        }

        var root = filterContainer.closest('.block') || document.body;

        return Str.get_strings([
            {key: 'filter:loading', component: 'block_enhancedcourseoverview'},
            {key: 'filter:nomatches', component: 'block_enhancedcourseoverview'},
            {key: 'filter:showing', component: 'block_enhancedcourseoverview'}
        ]).then(function (strings) {
            var filter = new CourseFilter(root, filterContainer, {
                loading: strings[0],
                nomatches: strings[1],
                showing: strings[2]
            });

            filterContainer.querySelectorAll(SELECTORS.FILTER_BUTTON).forEach(function (button) {
                button.addEventListener('click', function (event) {
                    event.preventDefault();
                    button.classList.toggle('active');
                    filter.refresh();
                });
            });

            filterContainer.querySelectorAll(SELECTORS.GROUP_TOGGLE).forEach(function (toggle) {
                toggle.addEventListener('click', function (event) {
                    event.preventDefault();
                    var group = toggle.closest(SELECTORS.GROUP);
                    var buttons = group.querySelectorAll(SELECTORS.FILTER_BUTTON);
                    var allActive = Array.prototype.every.call(buttons, function (button) {
                        return button.classList.contains('active');
                    });
                    buttons.forEach(function (button) {
                        button.classList.toggle('active', !allActive);
                    });
                    filter.refresh();
                });
            });

            filter.updateGroupVisibility();
            return filter.refresh();
        });
    };

    return {
        init: init
    };
});
